import "core-js/modules/es.array.push.js";
/*eslint-disable*/
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import SnackBar from "@/components/SnackBar.vue";
import { asset_dashboard_reports } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { GChart } from "vue-google-charts";
export default {
  components: {
    GChart,
    SnackBar
  },
  data() {
    return {
      chartData1: [["labels", "Data"]],
      chartData2: [["labels", "Data"]],
      chartData3: [["labels", "Data"]],
      chartOptions: {
        height: 350,
        legend: {
          position: "bottom"
        },
        chartArea: {
          top: 10,
          // Reduce space at the top
          height: "70%" // Adjust the chart area height
        }
      },
      chartOptions2: {
        // width:
        height: 350,
        // title: "Asset Categories",
        legend: {
          position: "bottom"
        },
        chartArea: {
          top: 10,
          height: "70%"
        }
      },
      chartOptions3: {
        // width:
        height: 350,
        title: "Asset Location",
        legend: {
          position: "bottom"
        },
        chartArea: {
          top: 10,
          height: "70%"
        }
      },
      graphdata: [],
      SnackBarComponent: {},
      loading: false,
      adminassetRecords: [],
      fixed: true,
      tableLoading: false,
      isVisible: false,
      adminassetHeaders: [{
        title: "Asset ID",
        key: "asset_prefix",
        sortable: false
      }, {
        title: "Category",
        key: "category_id_text",
        sortable: false
      }, {
        title: "Sub Category",
        key: "sub_category_id_text",
        sortable: false
      }, {
        title: "Location",
        key: "asset_location",
        sortable: false
      }, {
        title: "Assigned To",
        key: "asset_assined_to_name",
        sortable: false
      }, {
        title: "Verified On",
        key: "asset_verified_on",
        sortable: false
      }, {
        title: "QR Tagged",
        key: "asset_tagged_status",
        sortable: false
      }]
    };
  },
  async mounted() {
    this.isVisible = true;
    await this.get_asset_graph();
  },
  methods: {
    formate_date(value) {
      var data = formatdisplayDate(value);
      return data;
    },
    async get_asset_graph() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(asset_dashboard_reports, {
          input: {
            action_type: "ALL"
          }
        }));
        var response = JSON.parse(result.data.asset_dashboard_reports).data;
        // console.log(response);
        this.loading = false;
        this.graphdata = response.asset_details;
        this.adminassetRecords = response.recently_added_assets;
        for (let i = 0; i < this.graphdata.length; i++) {
          this.chartData1.push([this.graphdata[i].name, this.graphdata[i].value]);
        }
        var graphdata1 = response.asset_category_details;
        for (let i = 0; i < graphdata1.length; i++) {
          this.chartData2.push([graphdata1[i].category_name, graphdata1[i].asset_count]);
        }
        var graphdata2 = response.assets_by_location;
        for (let i = 0; i < graphdata2.length; i++) {
          this.chartData3.push([graphdata2[i].name, graphdata2[i].value]);
        }

        // console.log(this.chartData1);
      } catch (error) {
        this.loading = false;
        console.log(error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
